from pathlib import Path
import html,json
root=Path('artifacts/water')
views=[('coast-drive','A calmer, richer Pacific','Sky reflections and fine ripples carry through the driving view.'),('forest-drive','Water beside the redwoods','The ocean reflects the scene along every region.'),('headlands-drive','The last stretch of coast','Distant water settles into the horizon.'),('water-close','Swell and sunlight','Broad waves and smaller wind ripples move at different scales.'),('shoreline','Where the waves meet land','Teal shallows, broken surf and foam around the rocks.'),('ocean-wide','Room to breathe','A softer balance of light and water, with a gently moving surface.'),('station-approach','Beside a familiar stop','The reflected coast gives the water a stronger connection to the scene.'),('headland-shore','Beyond the road','The shoreline follows the shape of the land.')]

cards=''.join(f'''<article class="card"><div class="compare" data-view="{key}"><img class="after" src="after/high-{key}.png" alt="{html.escape(title)} after the water pass"><img class="before" src="before/high-{key}.png" alt="{html.escape(title)} before the water pass"><span class="tag old">Before</span><span class="tag new">After</span><div class="divider"></div></div><div class="body"><h3>{title}</h3><p>{description}</p><label>Compare <input aria-label="Compare before and after: {title}" type="range" min="0" max="100" value="30"></label></div></article>''' for key,title,description in views)
scores=[]
if (root/'critics.json').exists():scores=json.loads((root/'critics.json').read_text(encoding='utf8'))['judges']
critics='<h2>A fresh look at the whole coast</h2><table><thead><tr><th>Critic</th><th>Scores / 10</th><th>Finding</th></tr></thead><tbody>'+''.join(f'<tr><td>{html.escape(x["label"])}</td><td>Visual {x["overall"]:.1f}<br>Water {x["water"]:.1f}</td><td>{html.escape(x["finding"])}</td></tr>' for x in scores)+'</tbody></table><p class="note">One independent panel round after the water pass. These visual reviews used supplied renders and exported motion frames. The 9.3 graphics target remains unmet; driving and audio were not regraded.</p>' if scores else ''

page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pacific Run · the Pacific water</title><style>
video{width:100%;max-height:700px;display:block;border:1px solid #384a48;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:13px;text-align:left;border-bottom:1px solid #384a48}td:nth-child(2){white-space:nowrap;color:#dfc28e}*{box-sizing:border-box}body{margin:0;background:#122124;color:#eee9d6;font:16px/1.6 system-ui}main{max-width:1380px;margin:auto;padding:45px 30px 70px}small{color:#dab477;text-transform:uppercase;letter-spacing:.17em;font-size:12px}h1{font:500 clamp(34px,5vw,58px)/1.12 Georgia;margin:12px 0 18px;max-width:860px}h2{font-weight:500;margin:38px 0 18px}h3{font-size:20px;font-weight:500;margin:0 0 7px}p{max-width:840px;color:#afc0b8}nav{display:flex;gap:25px;flex-wrap:wrap;margin:25px 0}a{color:#e2c08b}a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid #efc78d;outline-offset:4px}.preset{display:flex;align-items:center;gap:10px;padding:15px 19px;background:#1b2e31;border-left:2px solid #c3a365}.preset span{margin-right:8px;color:#c1cbbc}button{font:inherit;background:#283d3d;border:1px solid #4b5d57;color:#d7dfcf;border-radius:4px;padding:7px 16px;cursor:pointer}button[aria-pressed=true]{background:#bd9b65;color:#172426;border-color:#d1b17a}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{background:#1d3033;border:1px solid #384a48;border-radius:8px;overflow:hidden}.compare{position:relative;aspect-ratio:14/9;--split:30%;overflow:hidden}.compare img{position:absolute;width:100%;height:100%;object-fit:cover}.before{clip-path:inset(0 calc(100% - var(--split)) 0 0)}.divider{position:absolute;left:var(--split);height:100%;border-left:2px solid #dec89c;pointer-events:none}.tag{position:absolute;top:14px;background:#132424cc;padding:3px 10px;font-size:11px;letter-spacing:.12em;text-transform:uppercase}.old{left:13px}.new{right:13px}.body{padding:18px 20px}.body p{font-size:14px;margin:0 0 16px}label{display:flex;align-items:center;gap:15px;color:#c7d3c5;font-size:12px}input{flex:1;min-width:0;accent-color:#c7ab78}.studies{grid-template-columns:repeat(3,minmax(0,1fr))}.study img{width:100%;display:block;aspect-ratio:14/9;object-fit:cover}.note{font-size:13px;color:#b1bfb5;margin:18px 0 26px}.phone{width:220px;max-width:100%;border-radius:6px;border:1px solid #45564e}@media(max-width:760px){main{padding:30px 18px}.grid,.studies{grid-template-columns:1fr}.preset{flex-wrap:wrap}.preset span{width:100%}nav{gap:17px}}
</style><main><small>Pacific Run · water</small><h1>A living Pacific, beside every mile.</h1><p>Gentle swell, wind ripples and reflections bring the ocean into the world. Broken waves wash along the shoreline, and foam gathers around the weathered rocks.</p><nav><a href="/">Go for a drive →</a><a href="/artifacts/road-land/road-gallery.html">Road & land →</a><a href="/artifacts/world-life/world-gallery.html">The living coast →</a><a href="/artifacts/juice/detail-gallery.html">Vehicle collection →</a></nav><video controls playsinline muted loop preload="metadata" poster="after/high-water-close.png" aria-label="In-engine ocean, shoreline and driving showcase"><source src="water-showcase.webm" type="video/webm"><source src="water-showcase.mp4" type="video/mp4"></video><p class="note">Watch the water move, then compare the same views below.</p><div class="preset"><span>Compare the graphics presets</span><button data-quality="high" aria-pressed="true">High</button><button data-quality="balanced" aria-pressed="false">Balanced</button></div><p class="note">Drag each comparison slider. The before and after views show the same locations under the same lighting.</p><div class="grid">'''+cards+'''</div>'''+critics+'''<h2>Along the water on a smaller screen</h2><img class="phone" src="after/phone-drive.png" alt="The updated coastal roadway in the phone driving view"><p class="note">The Balanced preset keeps the same water surface with smaller reflection captures.</p></main><script>
for(const card of document.querySelectorAll('.card')){const range=card.querySelector('input');if(range)range.addEventListener('input',()=>card.querySelector('.compare').style.setProperty('--split',range.value+'%'));}
for(const button of document.querySelectorAll('[data-quality]'))button.addEventListener('click',()=>{const quality=button.dataset.quality;for(const b of document.querySelectorAll('[data-quality]'))b.setAttribute('aria-pressed',String(b===button));for(const box of document.querySelectorAll('[data-view]')){box.querySelector('.before').src='before/'+quality+'-'+box.dataset.view+'.png';box.querySelector('.after').src='after/'+quality+'-'+box.dataset.view+'.png';}});
</script></html>'''
(root/'water-gallery.html').write_text(page,encoding='utf8')
